package com.bank.fibonacci;

import java.util.*;
import java.util.logging.*;

public class FibonacciDemo {
    private static final Logger log = Logger.getLogger("Fibonacci");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        FibonacciService service = new FibonacciService();
        log.info(() -> "First 20 Fibonacci: " + service.fibonacci(20));
    }
}

// ─── Would be in service/FibonacciService.java ───
class FibonacciService {
    List<Long> fibonacci(int count) {
        return java.util.stream.Stream.iterate(
                new long[]{0, 1},                       // seed pair {a, b}
                f -> new long[]{f[1], f[0] + f[1]})      // advance → {b, a+b}
            .map(f -> f[0])                              // take first of each pair
            .limit(count)                                // bound the infinite stream
            .toList();
    }
}
